-- Add conservative, name-based product content without overwriting existing editorial data.
UPDATE public.products AS product
SET
  description = COALESCE(NULLIF(product.description, ''), content.description),
  seo_title = COALESCE(NULLIF(product.seo_title, ''), content.seo_title),
  seo_description = COALESCE(NULLIF(product.seo_description, ''), content.seo_description),
  attributes = product.attributes || content.attributes
